#!/usr/bin/env python3
# reserve_L48f.py — 새 과 L48f(짚단 부부의 혼례와 이혼 · 세계 s48 의 f) — 두 층 헛간의 위층: 감수 1분열(전기 I 다섯 토막 · 접합 · 교차 · 키아즈마 · 중기 I · 후기 I · 말기 I).
#  L13c 부터의 방식 — 「가을 잔칫날, 짚단 부부가 천막 안에서 혼례를 치르고 춤판에서 갈라선다」 한 장면(Gemini 카본 높음이 통째로 + 구역 편집 5 + PIL).
import json
P = '/tmp/b2/tools/hooks.json'
txt = open(P, encoding='utf-8').read(); d = json.loads(txt)
assert json.dumps(d, ensure_ascii=False, indent=1) == txt
R = d['_심볼예약']
B = '[2026-11-15 새 과 L48f]'
new = {
 '남색 짚단(검은 실크해트를 쓴 신랑) · 하늘색 짚단(흰 면사포를 쓴 신부)': f'상동염색체의 아버지 쪽 · 어머니 쪽 전용 {B} — L48f 전체 · L48g 로 이어짐(옛 s47p01 의 짙은 남색 실 · 옅은 하늘색 실). 같은 키 한 쌍 = 상동 · 키 큰 쌍 / 작은 쌍 = 서로 다른 염색체. 모자 · 면사포는 할머니 · 이발사 곁 · 춤판에만(A 자 · 수레의 부부엔 없음 — 빛깔로 읽는다). ⚠ L48a 의 금빛 · 초록 짚단은 「서로 다른 염색체 둘」(부모 구분 없음).',
 '국수 가락처럼 가는 남색 · 하늘색 짚 실(짝 없이 흩어짐 · 묶이지 않음)': f'세사기(細絲期 — 가는 실 · 응축 시작 · 상동이 아직 떨어짐) 전용 {B} — L48f s2. ⚠ Gemini 첫 그림은 잿빛 실이라 두 빛깔이 안 갈렸다(일치 검사 1회 △) → 구역 편집 ZS.',
 '머릿수건 할머니 중매쟁이가 두 짚단을 나란히 세우고 감는 엮은 짚 띠(두루마리)': f'접합(시냅시스) · 접합사(시냅토네마 복합체)가 생기는 때 = 접합기 전용 {B} — L48f s3(아랫도리에 한 바퀴 · 위는 벌어짐 = 지금 엮는 중) · s4(몸통을 여러 바퀴 = 길이 내내 단단히 결착 → 교차를 도움) · s7(바닥에 풀린 띠 = 복사기에 접합사가 사라짐). ⚠ 기출은 접합사를 「지퍼 같은 구조」라 부르지만 【지퍼】는 DNA 전용 — 띠로 그린다. ⚠ 띠 겉의 잔 점이 가까이서 「손글씨 줄」로 읽혀(일치 검사 2회 (가)) PIL `strip_marks` 로 지웠다.',
 '걸상 위 줄무늬 앞치마 이발사가 짚단 끝을 잘라 짝의 짚단에 꽂음': f'교차(태사기 — 유전자 교환이 실제로 활발 · DNA 절단 → 비자매 염색분체의 상응 부위와 재연결 → 재조합 염색체) 전용 {B} — L48f s5 · s6. 이발사 손의 남색 한 줌(신랑에게서 자름 → 신부에게) · 신랑 머리 왼쪽의 하늘색 끝(이미 바꿈) — 빛깔은 PIL. 춤판 X 짚단 넷의 안쪽(점선 쪽) 위 다발 끝도 짝의 빛깔(재조합 염색분체 — 다발 둘 중 하나만). 가위 = 【가위】(자르는 동작 일반 — 이름은 「맞바꿔 꽂기」가 나른다).',
 '아랫도리는 A 자로 벌어지고 꼭대기가 X 로 엇걸린 남색 · 하늘색 짚단(양쪽에서 붙든 두 소년 · 바닥에 풀린 띠)': f'복사기(複絲期 — 접합사가 풀려 상동이 살짝 벌어지고 교차 자리가 X 자 키아즈마로 보임) 전용 {B} — L48f s7. ⚠ 교차는 앞(태사기)에서 이미 · 여기선 흔적(함정). X = 【_글자모양사전】 X(키아즈마).',
 '찢긴 천막 옆구리로 짧게 뭉친 짚단 부부를 싣고 나가는 외바퀴 수레': f'이동기(移動期 — 가장 짧고 굵게 응축 · 핵막 소실 · 옮겨 감) 전용 {B} — L48f s8. ⚠ 【둥근 천 덮개를 씌운 손수레】(L48d 수송소포)와 다르다 — 덮개 없음 · 외바퀴 · 짚단을 실음.',
 '등을 맞댄 두 아이가 막대로 서로 반대쪽으로 굴리는 검은 쇠 굴렁쇠(밧줄 토막을 매단)': f'전기(I)에 유사분열과 같은 셋 — 중심체 이동(반대쪽으로 굴림) · 방추사 형성(매달린 밧줄 토막) · (핵막 소실은 찢긴 천막) 전용 {B} — L48f s9. 검은 쇠고리 = 극(【헛간 벽에 박힌 검은 쇠고리(밧줄이 나옴)】). ⚠ 「이야기와 따로 노는 장식」으로도 읽혔다(일치 검사 3회 (다)) — 말이 굴렁쇠 → 춤판 쇠고리로 잇는다.',
 '흰 점선을 사이에 두고 짝째로 마주 선 X 짚단 부부 둘(큰 쌍은 남색이 왼쪽 · 작은 쌍은 하늘색이 왼쪽)': f'중기 I — 상동쌍이 짝째로 중기판에 · 한 상동의 두 자매염색분체는 같은 극(짚단 하나에 밧줄 한 가닥 → 같은 쪽 쇠고리) · 어느 쪽을 볼지는 쌍마다 따로(→ L48g 독립 분리) 전용 {B} — L48f s10. ⚠ L48a 셋째 칸(유사분열 중기)은 짚단 하나씩 점선 위 · 양쪽 밧줄이 한 짚단에.',
 '쇠고리에 맨 밧줄을 당기는 줄다리기 사내들 + 공중에 튀는 끊긴 은빛 C 자 고리 조각 + 허리 고리만 남아 X 로 벌어진 짚단': f'후기 I — 팔의 코헤신 분해 → 상동이 방추장치에 끌려 각각 반대 극(자매는 동원체 코헤신으로 아직 붙음 → 감수 2분열 L48g) 전용 {B} — L48f s11. 짚단은 두 다발(자매) — 팔 고리가 끊기자 X 로 벌어짐(= L48a 의 가위표 짚단 꼴). C 자 조각은 「말굽 · 콧수염」으로도 읽힌다(일치 검사 3회).',
 '조끼 차림 목수가 흰 점선 위에 박는 낮은 판자 칸막이 + 양쪽의 계단 보이는 뚜껑 문': f'말기 I · 세포질분열 — 딸세포 둘 · 둘 다 반수체(쌍마다 하나씩 · 아직 복제된 X) · 뚜껑 문 아래 = 아래층(감수 2분열 · L48g) 전용 {B} — L48f s12. ⚠ 판자 칸막이는 「방이 둘로」만 나른다 — L48b 창고 한가운데 공중에 뜬 새 널빤지(식물 세포판 · 가운데에서 바깥으로)와 꼴 · 자리가 다르다(이쪽은 바닥 앞 가장자리에서 들어오는 낮은 울). 동물 세포질분열은 L48b 풍선집의 살구색 줄(수축환). ⚠ 【멜빵바지 목수 · 나무망치 · 반쯤 박힌 나무못】(L38a 인산이에스터 결합)과 다르다 — 쇠망치 · 쇠못 · 못 상자.',
}
for k, v in new.items():
    assert k not in R, k
    R[k] = v
def add(key, note):
    v = R[key]; assert isinstance(v, str), key
    R[key] = v + ' ' + note
add('가위', f'★ {B} L48f s5 걸상 위 줄무늬 앞치마 이발사의 가위 = 교차(짚단 끝을 잘라 짝의 짚단에 꽂음 — 이름은 「맞바꿔 꽂기」가 나른다 · 옛 s47p01 의 가위).')
add('모자', f'★ {B} L48f 짚단 신랑의 검은 실크해트 = 신랑(아버지 쪽 상동염색체) — 신부의 흰 면사포와 짝으로만 뜻이 있다. 5′ 캡의 겨자색 중산모(띠 앞머리)와 꼴 · 자리가 다르다(짚단 머리 위 · 높은 원통).')
add('짚 다발을 끼운 은빛 쇠 고리', f'★ {B} L48f — 춤판 짚단(두 다발 = 자매)의 팔 고리가 끊겨 C 자 조각으로 튐 = 후기 I 팔 코헤신 분해 · 허리 고리만 남음 = 동원체 코헤신(감수 2분열에 끊김 → L48g).')
add('헛간 벽에 박힌 검은 쇠고리(밧줄이 나옴)', f'★ {B} L48f — 춤판 왼쪽 기둥 · 오른쪽 벽의 쇠고리(줄다리기 밧줄이 매임 = 극 · 방추사) · 아이 둘이 반대쪽으로 굴리는 검은 쇠 굴렁쇠 = 중심체 이동(전기 I).')
add('돔 천막(둥근 지붕 · 문 하나)', f'★ {B} L48f 앞을 잘라 낸 커다란 빨강 · 흰 줄 돔 천막 = 감수 1분열 전기의 핵(그 안에서 짚단 혼례) · 위 가장자리가 너덜(사라질 채비 — L48a 첫째 칸) · 오른쪽 옆구리가 크게 찢김 = 이동기 핵막 소실.')
add('삼밧줄 / 금빛 밧줄', f'★ {B} L48f 줄다리기 삼밧줄(짚단 허리 → 사내 손 → 쇠고리) = 방추사 · 굴렁쇠에 매달린 밧줄 토막 = 방추사 형성 시작.')
add('지퍼', f'★ {B} L48f — 기출이 「지퍼 같은 구조」라 부르는 접합사(시냅토네마 복합체)는 지퍼로 그리지 않았다 → 할머니 중매쟁이의 엮은 짚 띠(옛 s47p01 은 지퍼였다).')
out = json.dumps(d, ensure_ascii=False, indent=1)
assert json.loads(out) == d
open(P, 'w', encoding='utf-8').write(out)
print('예약', len(R))
